<dt id="download">{{ $t('setting__download') }}</dt><dd><div class="gap-top"><base-checkbox id="setting_download_enable" :model-value="appSetting['download.enable']" :label="$t('setting__download_enable')" @update:model-value="updateSetting({'download.enable': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_skip_exist_file" :model-value="appSetting['download.skipExistFile']" :label="$t('setting__download_skip_exist_file')" @update:model-value="updateSetting({'download.skipExistFile': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_save_group_list_name" :model-value="appSetting['download.isSavePathGroupByListName']" :label="$t('setting_download_save_group_list_name')" @update:model-value="updateSetting({'download.isSavePathGroupByListName': $event})"></base-checkbox></div></dd><dd :aria-label="$t('setting__download_path_title')"><h3 id="download_path">{{ $t('setting__download_path') }}</h3><div><div class="p">{{ $t('setting__download_path_label') }}<span class="auto-hidden hover" :class="$style.savePath" :aria-label="$t('setting__download_path_open_label')" @click="openDirInExplorer(appSetting['download.savePath'])">{{ appSetting['download.savePath'] }}</span></div><div class="p"><base-btn class="btn" min @click="handleChangeSavePath">{{ $t('setting__download_path_change_btn') }}</base-btn></div></div></dd><dd><h3 id="download_max_num">{{ $t('setting__download_max_num') }}<svg-icon class="help-icon" name="help-circle-outline" :aria-label="$t('setting__download_max_num_tooltip')"></svg-icon></h3><div><p><base-selection class="gap-left" :class="$style.selectWidth" :model-value="appSetting['download.maxDownloadNum']" :list="maxNums" item-key="id" item-name="id" @change="handleUpdateMaxNum"></base-selection></p></div></dd><dd><h3 id="download_use_other_source">{{ $t('setting__download_use_other_source') }}<svg-icon class="help-icon" name="help-circle-outline" :aria-label="$t('setting__download_use_other_source_tip')"></svg-icon></h3><div><base-checkbox id="setting_download_isUseOtherSource" :model-value="appSetting['download.isUseOtherSource']" :label="$t('setting__is_enable')" @update:model-value="updateSetting({'download.isUseOtherSource': $event})"></base-checkbox></div><div></div></dd><dd :aria-label="$t('setting__download_name_title')"><h3 id="download_name">{{ $t('setting__download_name') }}</h3><div><base-checkbox class="gap-left" v-for="item in musicNames" :id="`setting_download_musicName_${item.value}`" :key="item.value" name="setting_download_musicName" :value="item.value" need :model-value="appSetting['download.fileName']" :label="item.name" @update:model-value="updateSetting({'download.fileName': $event})"></base-checkbox></div></dd><dd><h3 id="download_data_embed">{{ $t('setting__download_data_embed') }}</h3><div class="gap-top"><base-checkbox id="setting_download_isEmbedPic" :model-value="appSetting['download.isEmbedPic']" :label="$t('setting__download_embed_pic')" @update:model-value="updateSetting({'download.isEmbedPic': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_isEmbedLyric" :model-value="appSetting['download.isEmbedLyric']" :label="$t('setting__download_embed_lyric')" @update:model-value="updateSetting({'download.isEmbedLyric': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_isEmbedLyricT" :disabled="!appSetting['download.isEmbedLyric']" :model-value="appSetting['download.isEmbedLyricT']" :label="$t('setting__download_embed_tlyric')" @update:model-value="updateSetting({'download.isEmbedLyricT': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_isEmbedLyricR" :disabled="!appSetting['download.isEmbedLyric']" :model-value="appSetting['download.isEmbedLyricR']" :label="$t('setting__download_embed_rlyric')" @update:model-value="updateSetting({'download.isEmbedLyricR': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_isEmbedLyricLx" :disabled="!appSetting['download.isEmbedLyric']" :model-value="appSetting['download.isEmbedLyricLx']" :label="$t('setting__download_embed_lxlyric')" @update:model-value="updateSetting({'download.isEmbedLyricLx': $event})"></base-checkbox></div></dd><dd :aria-label="$t('setting__download_lyric_title')"><h3 id="download_lyric">{{ $t('setting__download_lyric') }}</h3><div class="gap-top"><base-checkbox id="setting_download_isDownloadLrc" :model-value="appSetting['download.isDownloadLrc']" :label="$t('setting__is_enable')" @update:model-value="updateSetting({'download.isDownloadLrc': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_isDownloadTLrc" :disabled="!appSetting['download.isDownloadLrc']" :model-value="appSetting['download.isDownloadTLrc']" :label="$t('setting__download_tlyric')" @update:model-value="updateSetting({'download.isDownloadTLrc': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_isDownloadRLrc" :disabled="!appSetting['download.isDownloadLrc']" :model-value="appSetting['download.isDownloadRLrc']" :label="$t('setting__download_rlyric')" @update:model-value="updateSetting({'download.isDownloadRLrc': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_download_isDownloadLxLrc" :disabled="!appSetting['download.isDownloadLrc']" :model-value="appSetting['download.isDownloadLxLrc']" :label="$t('setting__download_lxlyric')" @update:model-value="updateSetting({'download.isDownloadLxLrc': $event})"></base-checkbox></div></dd><dd><h3 id="download_lyric_format">{{ $t('setting__download_lyric_format') }}<svg-icon class="help-icon" name="help-circle-outline" :aria-label="$t('setting__download_lyric_format_tip')"></svg-icon></h3><div><base-checkbox class="gap-left" v-for="item in lrcFormatList" :id="`setting_download_lrcFormat_${item.id}`" :key="item.id" name="setting_download_lrcFormat" need :model-value="appSetting['download.lrcFormat']" :value="item.id" :label="item.name" @update:model-value="updateSetting({'download.lrcFormat': $event})"></base-checkbox></div></dd>