<dt id="hot_key">{{ $t('setting__hot_key') }}</dt><dd><h3 id="hot_key_local_title">{{ $t('setting__hot_key_local_title') }}</h3><div><base-checkbox id="setting_download_hotKeyLocal" v-model="current_hot_key.local.enable" :label="$t('setting__is_enable')" @change="handleHotKeySaveConfig"></base-checkbox></div><div :class="$style.hotKeyContainer" :style="{ opacity: current_hot_key.local.enable ? 1 : .6 }"><div v-for="(item, index) in allHotKeys.local" :key="index" :class="$style.hotKeyItem"><h4 :class="$style.hotKeyItemTitle">{{ $t('setting__hot_key_' + item.name) }}</h4><base-input :class="$style.hotKeyItemInput" readonly :auto-paste="false" :placeholder="$t('setting__hot_key_unset_input')" :value="hotKeyConfig.local[item.name] &amp;&amp; formatHotKeyName(hotKeyConfig.local[item.name].key)" @keyup.prevent @focus="handleHotKeyFocus($event, item, 'local')" @blur="handleHotKeyBlur($event, item, 'local')"></base-input></div></div></dd><dd><h3 id="hot_key_global_title">{{ $t('setting__hot_key_global_title') }}</h3><div><base-checkbox id="setting_download_hotKeyGlobal" v-model="current_hot_key.global.enable" :label="$t('setting__is_enable')" @change="handleEnableHotKey"></base-checkbox></div><div :class="$style.hotKeyContainer" :style="{ opacity: current_hot_key.global.enable ? 1 : .6 }"><div v-for="(item, index) in allHotKeys.global" :key="index" :class="$style.hotKeyItem"><h4 :class="$style.hotKeyItemTitle">{{ $t('setting__hot_key_' + item.name) }}</h4><base-input :class="[$style.hotKeyItemInput, hotKeyConfig.global[item.name] &amp;&amp; hotKeyStatus[hotKeyConfig.global[item.name].key] &amp;&amp; hotKeyStatus[hotKeyConfig.global[item.name].key].status === false ? $style.hotKeyFailed : null]" :value="hotKeyConfig.global[item.name] &amp;&amp; formatHotKeyName(hotKeyConfig.global[item.name].key)" :auto-paste="false" readonly :placeholder="$t('setting__hot_key_unset_input')" @input.prevent @focus="handleHotKeyFocus($event, item, 'global')" @blur="handleHotKeyBlur($event, item, 'global')"></base-input></div></div></dd>