<dt id="basic">{{ $t('setting__basic') }}</dt><dd><div><div class="gap-top"><base-checkbox id="setting_show_animate" :model-value="appSetting['common.isShowAnimation']" :label="$t('setting__basic_show_animation')" @update:model-value="updateSetting({'common.isShowAnimation': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_animate" :disabled="!appSetting['common.isShowAnimation']" :model-value="appSetting['common.randomAnimate']" :label="$t('setting__basic_animation')" @update:model-value="updateSetting({'common.randomAnimate': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_start_in_fullscreen" :model-value="appSetting['common.startInFullscreen']" :label="$t('setting__basic_start_in_fullscreen')" @update:model-value="updateSetting({'common.startInFullscreen': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting_to_tray" :model-value="appSetting['tray.enable']" :label="$t('setting__basic_to_tray')" @update:model-value="updateSetting({'tray.enable': $event})"></base-checkbox></div><div class="p gap-top"><base-btn class="btn" min @click="isShowPlayTimeoutModal = true">{{ $t('setting__play_timeout')}} {{ timeLabel ? ` (${timeLabel})` : '' }}</base-btn></div></div></dd><dd><h3 id="basic_theme">{{ $t('setting__basic_theme') }}</h3><div><ul :class="$style.theme"><li v-for="theme in themeList" :key="theme.id" :aria-label="theme.name" :style="theme.styles" :class="[$style.themeItem, {[$style.active]: themeId == theme.id}]" @click="toggleTheme(theme)" @contextmenu="handleEditTheme(theme)"><div :class="$style.bg"></div><span :class="$style.label">{{ theme.name }}</span></li><li v-if="showAllTheme || themeId == 'auto'" :aria-label="$t('theme_auto_tip')" :style="autoTheme" :class="[$style.themeItem, $style.auto, {[$style.active]: themeId == 'auto'}]" @click="handleSetThemeAuto" @contextmenu="isShowThemeSelectorModal = true"><div :class="$style.bg"><div :class="$style.bgContent"><div :class="$style.light"></div><div :class="$style.dark"></div></div></div><span :class="$style.label">{{ $t('theme_auto') }}</span></li><li v-if="showAllTheme" :aria-label="$t('theme_add')" :class="[$style.themeItem, $style.add]" @click="handleEditTheme()"><div :class="$style.bg"><div :class="$style.bgContent"><svg-icon :class="$style.icon" name="plus"></svg-icon></div></div><span :class="$style.label">{{ $t('theme_add') }}</span></li><li v-if="!showAllTheme" :aria-label="$t('theme_more_btn_show')" :class="[$style.themeItem, $style.moreThme]" @click="showAllTheme = true"><span :class="$style.label">{{ $t('theme_more_btn_show') }}</span><svg-icon name="angle-right-solid" :class="$style.activeIcon"></svg-icon></li></ul></div></dd><dd><h3 id="basic_source">{{ $t('setting__basic_source') }}</h3><div><div class="gap-top" v-for="item in apiSources" :key="item.id"><base-checkbox :id="`setting_api_source_${item.id}`" name="setting_api_source" need :model-value="appSetting['common.apiSource']" :disabled="item.disabled" :value="item.id" :aria-label="item.label" @update:model-value="updateSetting({'common.apiSource': $event})"><span :class="$style.sourceLabel">{{ item.name }}<span v-if="item.desc" :class="$style.desc">{{ item.desc }}</span><span v-if="item.statusLabel" :class="$style.status">{{ item.statusLabel }}</span></span></base-checkbox></div><div class="p gap-top"><base-btn class="btn" min @click="isShowUserApiModal = true">{{ $t('setting__basic_source_user_api_btn') }}</base-btn></div></div></dd><dd><h3 id="basic_window_size">{{ $t('setting__basic_window_size') }}</h3><div><base-checkbox class="gap-left" v-for="item in windowSizeList" :id="`setting_window_size_${item.id}`" :key="item.id" name="setting_window_size" need :model-value="appSetting['common.windowSizeId']" :disabled="isFullscreen" :value="item.id" :label="$t('setting__basic_window_size_' + item.name)" @update:model-value="updateSetting({'common.windowSizeId': $event})"></base-checkbox></div></dd><dd><h3 id="basic_font_size">{{ $t('setting__basic_font_size') }}</h3><div><base-checkbox class="gap-left" v-for="item in fontSizeList" :id="`setting_basic_font_size_${item.id}`" :key="item.id" name="setting_basic_font_size" need :model-value="appSetting['common.fontSize']" :value="item.id" :label="item.label" :disabled="isFullscreen" @update:model-value="updateSetting({'common.fontSize': $event})"></base-checkbox></div></dd><dd><h3 id="basic_font">{{ $t('setting__basic_font') }}</h3><div style="--selection-width: 12rem;"><base-selection class="gap-left" :list="fontList" :model-value="fonts[0]" item-key="id" item-name="label" @update:model-value="updateFonts($event, fonts[1])"></base-selection><base-selection class="gap-left" v-if="fonts[0]" :list="fontList" :model-value="fonts[1]" item-key="id" item-name="label" @update:model-value="updateFonts(fonts[0], $event)"></base-selection></div></dd><dd><h3 id="basic_lang">{{ $t('setting__basic_lang') }}</h3><div><base-checkbox class="gap-left" v-for="item in langList" :id="`setting_lang_${item.locale}`" :key="item.locale" name="setting_lang" need :model-value="appSetting['common.langId']" :value="item.locale" :label="item.name" @update:model-value="updateSetting({'common.langId': $event})"></base-checkbox></div></dd><dd><h3 id="basic_sourcename">{{ $t('setting__basic_sourcename') }}</h3><div><base-checkbox class="gap-left" v-for="item in sourceNameTypes" :id="`setting_abasic_sourcename_${item.id}`" :key="item.id" name="setting_basic_sourcename" need :model-value="appSetting['common.sourceNameType']" :value="item.id" :label="item.label" @update:model-value="updateSetting({'common.sourceNameType': $event})"></base-checkbox></div></dd><dd><h3 id="basic_control_btn_position">{{ $t('setting__basic_control_btn_position') }}</h3><div><base-checkbox class="gap-left" v-for="item in controlBtnPositionList" :id="`setting_basic_control_btn_position_${item.id}`" :key="item.id" name="setting_basic_control_btn_position" need :model-value="appSetting['common.controlBtnPosition']" :value="item.id" :label="item.name" @update:model-value="updateSetting({'common.controlBtnPosition': $event})"></base-checkbox></div></dd><dd><h3 id="basic_playbar_progress_style">{{ $t('setting__basic_playbar_progress_style') }}</h3><div><base-checkbox class="gap-left" id="setting_basic_playbar_progress_style_mini" name="setting_basic_playbar_progress_style" need :model-value="appSetting['common.playBarProgressStyle']" value="mini" :label="$t('setting__basic_playbar_progress_style_mini')" @update:model-value="updateSetting({'common.playBarProgressStyle': $event})"></base-checkbox><base-checkbox class="gap-left" id="setting_basic_playbar_progress_style_middle" name="setting_basic_playbar_progress_style" need :model-value="appSetting['common.playBarProgressStyle']" value="middle" :label="$t('setting__basic_playbar_progress_style_middle')" @update:model-value="updateSetting({'common.playBarProgressStyle': $event})"></base-checkbox><base-checkbox class="gap-left" id="setting_basic_playbar_progress_style_full" name="setting_basic_playbar_progress_style" need :model-value="appSetting['common.playBarProgressStyle']" value="full" :label="$t('setting__basic_playbar_progress_style_full')" @update:model-value="updateSetting({'common.playBarProgressStyle': $event})"></base-checkbox></div></dd><ThemeSelectorModal v-model="isShowThemeSelectorModal"></ThemeSelectorModal><ThemeEditModal v-model="isShowThemeEditModal" :theme-id="editThemeId" @submit="handleRefreshTheme"></ThemeEditModal><play-timeout-modal v-model="isShowPlayTimeoutModal"></play-timeout-modal><user-api-modal v-model="isShowUserApiModal"></user-api-modal>