<material-modal :show="modelValue" bg-close teleport="#view" @close="$emit('update:modelValue', false)"><main :class="$style.main"><h2>{{ $t('setting__sync_server_device_list_title') }}</h2><ul class="scroll" v-if="historyDeviceList.length" :class="$style.content"><li v-for="(device, index) in historyDeviceList" :key="device.id" :class="$style.listItem"><div :class="$style.listLeft"><span :class="$style.name"><svg-icon v-if="device.isMobile" name="phone" style="margin-right: 0.2rem; vertical-align: -0.2em;"></svg-icon>{{ device.name }}</span><span :class="$style.desc">{{ $t('setting__sync_server_device_list_time', { time: device.lastConnectDate }) }}</span></div><base-btn :class="$style.listBtn" outline :aria-label="$t('setting__sync_server_device_list_btn_remove')" @click.stop="handleRemove(index)"><svg v-once version="1.1" xmlns="http://www.w3.org/2000/svg" xlink="http://www.w3.org/1999/xlink" viewBox="0 0 212.982 212.982" space="preserve"><use xlink:href="#icon-delete"></use></svg></base-btn></li></ul><div v-else :class="$style.content"><div :class="$style.noitem">{{ $t('setting__sync_server_device_list_noitem') }}</div></div></main><div :class="$style.footer"><div :class="$style.tips">{{ $t('setting__sync_server_device_list_tips') }}</div></div></material-modal>