<div :class="$style.container"><ul><li v-for="item in comments" :key="item.id" :class="$style.listItem"><div :class="$style.content"><div :class="$style.left"><img :class="$style.avatar" :src="item.avatar || commentDefImg" @error="handleUserImg"></div><div :class="$style.right"><div :class="$style.info"><div :class="$style.baseInfo"><div class="select" :class="$style.name">{{ item.userName }}</div><div :class="$style.metaInfo"><time v-if="item.timeStr" :class="$style.label">{{ timeFormat(item.timeStr) }}</time><div v-if="item.location" :class="$style.label">{{ $t('comment__location', { location: item.location }) }}</div></div></div><div v-if="item.likedCount != null" :class="$style.likes"><svg :class="$style.likesIcon" version="1.1" xmlns="http://www.w3.org/2000/svg" xlink="http://www.w3.org/1999/xlink" viewBox="0 0 512 512" space="preserve"><use xlink:href="#icon-thumbs-up"></use></svg>{{ item.likedCount }}</div></div><p class="select" :class="$style.comment_text">{{ item.text }}</p><div v-if="item.images?.length" :class="$style.comment_images"><img v-for="(url, index) in item.images" :key="index" :src="url" loading="lazy" decoding="async"></div></div></div><comment-floor v-if="item.reply &amp;&amp; item.reply.length" :class="$style.reply_floor" :comments="item.reply"></comment-floor></li></ul></div>