<div class="comment" ref="dom_container" :class="$style.comment"><div :class="$style.commentHeader"><h3>{{ $t('comment__title', { name: currentMusicInfo.name }) }}</h3><div :class="$style.commentHeaderBtns"><div :class="$style.commentHeaderBtn" :aria-label="$t('comment__refresh')" @click="handleShowComment"><svg version="1.1" xmlns="http://www.w3.org/2000/svg" xlink="http://www.w3.org/1999/xlink" style="transform: rotate(45deg);" viewBox="0 0 24 24" space="preserve"><use xlink:href="#icon-refresh"></use></svg></div><div :class="$style.commentHeaderBtn" @click="$emit('close')"><svg version="1.1" xmlns="http://www.w3.org/2000/svg" xlink="http://www.w3.org/1999/xlink" viewBox="0 0 24 24" space="preserve"><use xlink:href="#icon-close"></use></svg></div></div></div><div :class="$style.commentMain"><template v-if="available"><header :class="$style.tab_header"><button type="button" :class="[$style.commentType, { [$style.active]: tabActiveId == 'hot' }]" @click="handleToggleTab('hot')">{{ $t('comment__hot_title') }} ({{ hotComment.total }})</button><button type="button" :class="[$style.commentType, { [$style.active]: tabActiveId == 'new' }]" @click="handleToggleTab('new')">{{ $t('comment__new_title') }} ({{ newComment.total }})</button></header><main ref="dom_tabMain" :class="$style.tab_main"><div :class="$style.tab_content"><div class="scroll" ref="dom_commentHot" :class="$style.tab_content_scroll"><p v-if="hotComment.isLoadError" :class="$style.commentLabel" style="cursor: pointer;" @click="handleGetHotComment(currentMusicInfo, hotComment.nextPage, hotComment.limit)">{{ $t('comment__hot_load_error') }}</p><p v-else-if="hotComment.isLoading &amp;&amp; !hotComment.list.length" :class="$style.commentLabel">{{ $t('comment__hot_loading') }}</p><comment-floor v-if="!hotComment.isLoadError &amp;&amp; hotComment.list.length" :class="[$style.commentFloor, hotComment.isLoading ? $style.loading : null]" :comments="hotComment.list"></comment-floor><p v-else-if="!hotComment.isLoadError &amp;&amp; !hotComment.isLoading" :class="$style.commentLabel">{{ $t('comment__no_content') }}</p><div :class="$style.pagination"><material-pagination :count="hotComment.total" :btn-length="5" :limit="hotComment.limit" :page="hotComment.page" @btn-click="handleToggleHotCommentPage"></material-pagination></div></div></div><div :class="$style.tab_content"><div class="scroll" ref="dom_commentNew" :class="$style.tab_content_scroll"><p v-if="newComment.isLoadError" :class="$style.commentLabel" style="cursor: pointer;" @click="handleGetNewComment(currentMusicInfo, newComment.nextPage, newComment.limit)">{{ $t('comment__new_load_error') }}</p><p v-else-if="newComment.isLoading &amp;&amp; !newComment.list.length" :class="$style.commentLabel">{{ $t('comment__new_loading') }}</p><comment-floor v-if="!newComment.isLoadError &amp;&amp; newComment.list.length" :class="[$style.commentFloor, newComment.isLoading ? $style.loading : null]" :comments="newComment.list"></comment-floor><p v-else-if="!newComment.isLoadError &amp;&amp; !newComment.isLoading" :class="$style.commentLabel">{{ $t('comment__no_content') }}</p><div :class="$style.pagination"><material-pagination :count="newComment.total" :btn-length="5" :limit="newComment.limit" :page="newComment.page" @btn-click="handleToggleCommentPage"></material-pagination></div></div></div></main></template><div v-else :class="$style.unavailable"><p>{{ $t('comment__unavailable') }}</p></div></div></div>