<material-modal :show="modelValue" bg-close teleport="#view" @close="handleClose"><main class="scroll" :class="$style.main"><h2>{{ $t('user_api__title') }}</h2><ul class="scroll" v-if="apiList.length" :class="$style.content"><li v-for="(api, index) in apiList" :key="api.id" :class="[$style.listItem, {[$style.active]: appSetting['common.apiSource'] == api.id}]"><div :class="$style.listLeft"><h3>{{ api.name }}<span v-if="api.version">{{ /^\d/.test(api.version) ? `v${api.version}` : api.version }}</span><span v-if="api.author">{{ api.author }}</span></h3><p>{{ api.description }}</p><div><base-checkbox :id="`user_api_${api.id}`" v-model="api.allowShowUpdateAlert" :class="$style.checkbox" :label="$t('user_api__allow_show_update_alert')" @change="handleChangeAllowUpdateAlert(api, $event)"></base-checkbox></div></div><base-btn :class="$style.listBtn" outline :aria-label="$t('user_api__btn_remove')" @click.stop="handleRemove(index)"><svg v-once version="1.1" xmlns="http://www.w3.org/2000/svg" xlink="http://www.w3.org/1999/xlink" viewBox="0 0 212.982 212.982" space="preserve"><use xlink:href="#icon-delete"></use></svg></base-btn></li></ul><div v-else :class="$style.content"><div :class="$style.noitem">{{ $t('user_api__noitem') }}</div></div><div :class="$style.note"><p :class="[$style.ruleLink]">{{ $t('user_api__readme') }}<span class="hover underline" aria-label="https://lxmusic.toside.cn/desktop/custom-source" @click="handleOpenUrl('https://lyswhut.github.io/lx-music-doc/desktop/custom-source')">FAQ</span></p><p>{{ $t('user_api__note') }}</p></div><div :class="$style.footer"><base-btn :class="$style.footerBtn" @click="isShowOnlineImportModal = true">{{ $t('user_api__btn_import_online') }}</base-btn><base-btn :class="$style.footerBtn" @click="handleImport">{{ $t('user_api__btn_import') }}</base-btn></div><UserApiOnlineImportModal v-model:show="isShowOnlineImportModal" @import="importUserApi"></UserApiOnlineImportModal></main></material-modal>