import { markRaw, markRawList, toRaw } from '@common/utils/vueTools';
import { allMusicList, defaultList, loveList, tempList, userLists, } from './state';
import { overwriteListPosition, overwriteListUpdateInfo, removeListPosition, removeListUpdateInfo } from '@renderer/utils/data';
import { LIST_IDS } from '@common/constants';
import { arrPush, arrUnshift } from '@common/utils/common';
export const setUserLists = (lists) => {
    userLists.splice(0, userLists.length, ...lists);
    return userLists;
};
export const setMusicList = (listId, musicList) => {
    const list = markRawList(musicList);
    allMusicList.set(listId, list);
    return list;
};
const overwriteMusicList = (id, list) => {
    // console.log(id, list)
    markRawList(list);
    let targetList = allMusicList.get(id);
    if (targetList) {
        targetList.splice(0, targetList.length);
        arrPush(targetList, list);
    }
    else {
        allMusicList.set(id, list);
    }
};
const removeMusicList = (id) => {
    allMusicList.delete(id);
};
const createUserList = ({ name, id, source, sourceListId, locationUpdateTime, }, position) => {
    if (position < 0 || position >= userLists.length) {
        userLists.push({
            name,
            id,
            source,
            sourceListId,
            locationUpdateTime,
        });
    }
    else {
        userLists.splice(position, 0, {
            name,
            id,
            source,
            sourceListId,
            locationUpdateTime,
        });
    }
};
const updateList = ({ name, id, source, sourceListId, meta, locationUpdateTime, }) => {
    let targetList;
    switch (id) {
        case defaultList.id:
        case loveList.id:
            break;
        case tempList.id:
            tempList.meta = meta ?? {};
            break;
        default:
            targetList = userLists.find(l => l.id == id);
            if (!targetList)
                return;
            targetList.name = name;
            targetList.source = source;
            targetList.sourceListId = sourceListId;
            targetList.locationUpdateTime = locationUpdateTime;
            break;
    }
};
const removeUserList = (id) => {
    const index = userLists.findIndex(l => l.id == id);
    if (index < 0)
        return;
    userLists.splice(index, 1);
    // removeMusicList(id)
};
const overwriteUserList = (lists) => {
    userLists.splice(0, userLists.length, ...lists);
};
