import { reactive, markRaw } from '@common/utils/vueTools';
import music from '@renderer/utils/musicSdk';
export const sources = markRaw([]);
export const listInfos = markRaw({
    all: reactive({
        page: 1,
        maxPage: 0,
        limit: 30,
        total: 0,
        list: [],
        key: null,
        noItemLabel: '',
    }),
});
export const maxPages = {};
for (const source of music.sources) {
    if (!music[source.id]?.musicSearch)
        continue;
    sources.push(source.id);
    listInfos[source.id] = reactive({
        page: 1,
        maxPage: 0,
        limit: 30,
        total: 0,
        list: [],
        key: '',
        noItemLabel: '',
    });
    maxPages[source.id] = 0;
}
sources.push('all');
