<dt id="network">{{ $t('setting__network') }}</dt><dd><h3 id="network_proxy_title">{{ $t('setting__network_proxy_title') }}</h3><div><div class="p"><base-checkbox id="setting_network_proxy_enable" :model-value="appSetting['network.proxy.enable']" :label="$t('setting__is_enable')" @update:model-value="updateSetting({'network.proxy.enable': $event})"></base-checkbox></div><div class="p"><base-input :model-value="appSetting['network.proxy.host']" :placeholder="proxy.envProxy ? proxy.envProxy.host : $t('setting__network_proxy_host')" @update:model-value="setHost"></base-input></div><div class="p"><base-input :model-value="appSetting['network.proxy.port']" :placeholder="proxy.envProxy ? proxy.envProxy.port : $t('setting__network_proxy_port')" @update:model-value="setPort"></base-input></div></div></dd>