<transition enter-active-class="animated slideInRight" leave-active-class="animated slideOutDown" @after-enter="handleAfterEnter" @after-leave="handleAfterLeave"><div v-if="isShowPlayerDetail" :class="[$style.container, { fullscreen: isFullscreen }]" @contextmenu="handleContextMenu"><div :class="$style.bg"></div><ControlBtnsLeftHeader v-if="appSetting['common.controlBtnPosition'] == 'left'"></ControlBtnsLeftHeader><ControlBtnsRightHeader v-else></ControlBtnsRightHeader><div :class="[$style.main, {[$style.showComment]: isShowPlayComment}]"><div class="left" :class="$style.left"><div :class="$style.info"><img v-if="musicInfo.pic" :class="$style.img" :src="musicInfo.pic"><div class="description" :class="['scroll', $style.description]"><p>{{ $t('player__music_name') }}{{ musicInfo.name }}</p><p>{{ $t('player__music_singer') }}{{ musicInfo.singer }}</p><p v-if="musicInfo.album">{{ $t('player__music_album') }}{{ musicInfo.album }}</p></div></div></div><transition enter-active-class="animated fadeIn" leave-active-class="animated fadeOut"><LyricPlayer v-if="visibled"></LyricPlayer></transition><music-comment v-if="visibled" :class="$style.comment" :show="isShowPlayComment" :music-info="playMusicInfo.musicInfo" @close="hideComment"></music-comment></div><transition enter-active-class="animated fadeIn" leave-active-class="animated fadeOut"><play-bar v-if="visibled"></play-bar></transition><transition enter-active-class="animated-slow fadeIn" leave-active-class="animated-slow fadeOut"><common-audio-visualizer v-if="appSetting['player.audioVisualization'] &amp;&amp; visibled"></common-audio-visualizer></transition></div></transition>