<dt id="update">{{ $t('setting__update') }}</dt><dd><div class="gap-top"><base-checkbox id="setting__update_tryAutoUpdate" :model-value="appSetting['common.tryAutoUpdate']" :label="$t('setting__update_try_auto_update')" @update:model-value="updateSetting({'common.tryAutoUpdate': $event})"></base-checkbox></div><div class="gap-top"><base-checkbox id="setting__update_showChangeLog" :model-value="appSetting['common.showChangeLog']" :label="$t('setting__update_show_change_log')" @update:model-value="updateSetting({'common.showChangeLog': $event})"></base-checkbox></div><div class="gap-top"><div class="gap-top"><div class="p small" @click="handleOpenDevTools">{{ $t('setting__update_current_label') }}{{ versionInfo.version }}</div><div class="p small" v-if="commit_id">{{ $t('setting__update_commit_id') }}<span class="select">{{ commit_id }}</span></div><div class="p small" v-if="commit_date">{{ $t('setting__update_commit_date') }}{{ commit_date }}</div></div><div class="p small gap-top">{{ $t('setting__update_latest_label') }}{{ versionInfo.newVersion && versionInfo.newVersion.version != '0.0.0' ? versionInfo.newVersion.version : $t('setting__update_unknown') }}</div><div class="p small" v-if="downloadProgress" style="line-height: 1.5;">{{ $t('setting__update_downloading') }}<br>{{ $t('setting__update_progress') }}{{ downloadProgress }}</div><template v-if="versionInfo.newVersion"><div class="p" v-if="versionInfo.isLatest"><span>{{ $t('setting__update_latest') }}</span></div><div class="p" v-else-if="versionInfo.isUnknown"><span>{{ $t('setting__update_unknown_tip') }}</span></div><div class="p" v-else-if="versionInfo.status != 'downloading'"><span>{{ $t('setting__update_new_version') }}</span></div><div class="p"><base-btn class="btn gap-left" min @click="showUpdateModal">{{ $t('setting__update_open_version_modal_btn') }}</base-btn></div></template><div class="p small" v-else-if="versionInfo.status =='checking'">{{ $t('setting__update_checking') }}</div></div></dd>