import { reactive, markRaw, shallowReactive } from '@common/utils/vueTools';
import music from '@renderer/utils/musicSdk';
export const sources = markRaw([]);
for (const source of music.sources) {
    if (!music[source.id]?.leaderboard?.getBoards)
        continue;
    sources.push(source.id);
}
export const boards = shallowReactive({});
export const listDetailInfo = reactive({
    list: [],
    total: 0,
    page: 1,
    limit: 30,
    key: null,
    source: null,
    id: '',
    noItemLabel: '',
});
