import { reactive, markRaw, ref, shallowReactive } from '@common/utils/vueTools';
import music from '@renderer/utils/musicSdk';
export const sources = markRaw([]);
export const sortList = markRaw({});
for (const source of music.sources) {
    const songList = music[source.id]?.songList;
    if (!songList)
        continue;
    sources.push(source.id);
    sortList[source.id] = songList.sortList;
}
