<dt id="sync">{{ $t('setting__sync') }}<button class="help-btn" :aria-label="$t('setting__sync_tip')" @click="openUrl('https://lyswhut.github.io/lx-music-doc/desktop/faq/sync')"><svg-icon name="help-circle-outline"></svg-icon></button></dt><dd><base-checkbox id="setting_sync_enable" :model-value="appSetting['sync.enable']" :label="$t('setting__sync_enable')" @update:model-value="updateSetting({ 'sync.enable': $event })"></base-checkbox></dd><dd><h3 id="sync_mode">{{ $t('setting__sync_mode') }}</h3><div><base-checkbox class="gap-left" id="setting_sync_mode_server" :disabled="sync.enable" :model-value="appSetting['sync.mode']" need value="server" :label="$t('setting__sync_mode_server')" @update:model-value="updateSetting({ 'sync.mode': $event })"></base-checkbox><base-checkbox class="gap-left" id="setting_sync_mode_client" :disabled="sync.enable" :model-value="appSetting['sync.mode']" need value="client" :label="$t('setting__sync_mode_client')" @update:model-value="updateSetting({ 'sync.mode': $event })"></base-checkbox></div></dd><SyncClient v-if="sync.mode == 'client'"></SyncClient><SyncServer v-else></SyncServer>