<material-modal :show="modelValue" teleport="#view" @close="handleCloseModal" @after-enter="$refs.dom_input.focus()"><main :class="$style.main"><h2>{{ $t('play_timeout') }}</h2><div :class="$style.content"><div :class="[$style.row, $style.inputGroup]"><base-input ref="dom_input" v-model="time" :class="$style.input" type="number"></base-input><p :class="$style.inputLabel">{{ $t('play_timeout_unit') }}</p></div><div :class="$style.row"><base-checkbox id="play_timeout_end" :model-value="appSetting['player.waitPlayEndStop']" :label="$t('play_timeout_end')" @update:model-value="updateSetting({'player.waitPlayEndStop': $event})"></base-checkbox></div><div :class="[$style.row, $style.tip, { [$style.show]: !!timeLabel }]"><p>{{ $t('play_timeout_tip', { time: timeLabel }) }}</p></div></div><div :class="$style.footer"><base-btn :class="$style.footerBtn" @click="handleCancel">{{ $t(timeLabel ? 'play_timeout_stop' : 'play_timeout_close') }}</base-btn><base-btn :class="$style.footerBtn" @click="handleConfirm">{{ $t(timeLabel ? 'play_timeout_update' : 'play_timeout_confirm') }}</base-btn></div></main></material-modal>