import { reactive, markRaw } from '@common/utils/vueTools';
import music from '@renderer/utils/musicSdk';
export const sources = markRaw([]);
export const sourceList = markRaw({
    all: reactive([]),
});
for (const source of music.sources) {
    if (!music[source.id]?.hotSearch)
        continue;
    sources.push(source.id);
    sourceList[source.id] = reactive([]);
}
sources.push('all');
const setList = (source, list) => {
    return sourceList[source] = list.slice(0, 20);
};
const setLists = (lists) => {
    let wordsMap = new Map();
    for (const { source, list } of lists) {
        if (!sourceList[source]?.length)
            sourceList[source] = list.slice(0, 20);
        for (let item of list) {
            item = item.trim();
            wordsMap.set(item, (wordsMap.get(item) ?? 0) + 1);
        }
    }
    const wordsMapArr = Array.from(wordsMap);
    wordsMapArr.sort((a, b) => a[0].localeCompare(b[0]));
    wordsMapArr.sort((a, b) => b[1] - a[1]);
    const words = wordsMapArr.map(item => item[0]);
    return sourceList.all = words.slice(0, sources.length * 10);
};
export const getList = async (source) => {
    if (source == 'all') {
        let task = [];
        for (const source of sources) {
            if (source == 'all')
                continue;
            task.push(sourceList[source]?.length
                ? Promise.resolve({ source, list: sourceList[source] })
                : (music[source]?.hotSearch.getList() ?? Promise.reject(new Error('source not found: ' + source))).catch((err) => {
                    console.log(err);
                    return { source, list: [] };
                }));
        }
        return Promise.all(task).then((results) => {
            return setLists(results);
        });
    }
    else {
        if (sourceList[source]?.length)
            return Promise.resolve(sourceList[source]);
        if (!music[source]?.hotSearch) {
            setList(source, []);
            return Promise.resolve([]);
        }
        return music[source]?.hotSearch.getList().then(data => setList(source, data.list));
    }
};
export const clearList = (source) => {
    sourceList[source] = [];
};
